        1,
        round(
            source_height * self.target_width / source_width + 1e-5
        ),
    )
    resize_width = self.target_width
else:
    resize_height = self.target_height
    resize_width = max(
        1,
        round(
            source_width * self.target_height / source_height + 1e-5
        ),
    )
